const questions=()=>s().questions;
const latestCustom=()=>new Map(s().custom.map(l=>[normalized(l.lemma),l]));const lexemes=()=>{const latest=latestCustom();return [...data.dictionary.filter(l=>!latest.has(normalized(l.lemma))),...latest.values()];};
const getLex=(id:string)=>lexemes().find(l=>l.id===id);
const senseById=(id:string)=>{for(const l of [...s().custom,...data.dictionary]){const sense=l.senses.find(x=>x.id===id);if(sense)return {lexeme:l,sense};}return undefined;};
