const personal=(id:string)=>s().overrides.find(o=>o.senseId===id);
const baseOwners=new Map(data.dictionary.flatMap(l=>l.senses.map(x=>[x.id,normalized(l.lemma)] as const)));const meaning=(sense:Sense)=>{const key=baseOwners.get(sense.id)||s().custom.find(l=>l.senses.some(x=>x.id===sense.id))?.lemma;const replacement=key?latestCustom().get(normalized(key))?.senses[0]:undefined;const chosen=replacement||sense;return personal(chosen.id)?.zh||chosen.zh;};
const date=(v:string)=>new Date(v).toLocaleDateString('zh-CN',{month:'short',day:'numeric'});
const routes=[['read','阅读练习','book'],['words','词汇库','list'],['notebook','我的生词本','bookmark'],['history','测试记录','chart'],['settings','设置','settings']];
let currentArticle='',exam:Mode='CET-4',topic='全部主题',length='全部长度',activeSet='',search='',wordFilter='all',sort='new',selected=new Set<string>(),focusReturn:HTMLElement|null=null;
let quiz:{questions:Question[];index:number;answers:Map<string,string>;submitted:boolean;selected:number;article?:string;isReview:boolean}|undefined;

function route(){const key=location.hash.slice(1)||'read';return routes.some(r=>r[0]===key)?key:'read';}
function announce(msg:string,undo?:()=>void){const box=document.getElementById('toast')!;box.innerHTML=`<span>${esc(msg)}</span>${undo?'<button id="undo-action">撤销</button>':''}`;box.classList.add('visible');const timer=setTimeout(()=>box.classList.remove('visible'),undo?10000:4500);box.querySelector('button')?.addEventListener('click',()=>{clearTimeout(timer);box.classList.remove('visible');undo?.();});}
async function change(fn:(state:UserState)=>void,success?:string){try{await repo.commit(fn);if(success)announce(success+(repo.mode==='临时模式'?'（仅本次会话，请导出）':''));return true;}catch(e){announce('保存失败，原有数据已保留。请导出备份并检查浏览器存储。');console.error('Storage write failed',e instanceof Error?e.name:'unknown');return false;}}
function applyTheme(){const theme=s().settings.theme==='system'?(matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light'):s().settings.theme;document.documentElement.dataset.theme=theme;document.documentElement.style.setProperty('--reading-size',s().settings.fontSize+'px');}
function render(){
  const selectionTools=document.getElementById('selection-tools');if(selectionTools)selectionTools.hidden=true;applyTheme();const r=route();app.innerHTML=`<aside class="sidebar"><a class="brand" href="#read"><span class="brand-mark">${icon('book')}</span><span>ContextFlow<small>语境流</small></span></a><nav aria-label="主导航">${routes.map(([id,label,ic])=>`<a href="#${id}" ${r===id?'aria-current="page"':''}>${icon(ic)}<span>${label}</span>${id==='notebook'&&s().vocabulary.length?`<em>${s().vocabulary.length}</em>`:''}</a>`).join('')}</nav><div class="sidebar-bottom"><div class="local-label"><span class="status-dot"></span>为专注留一点空间</div><p>在语境里理解，<br>在下一次相遇时记住。</p><button class="theme-btn" data-action="theme">${icon(s().settings.theme==='dark'?'sun':'moon')}<span>${s().settings.theme==='dark'?'切换浅色':'切换深色'}</span></button><div class="build-label">0.17.0 · 实时预览</div></div></aside><div class="workspace"><header class="topbar"><div class="crumb">我的学习空间 <span>/</span> ${routes.find(x=>x[0]===r)![1]}</div><div class="storage-state ${repo.mode==='临时模式'?'warning':''}" title="${esc(repo.detail)}"><span class="status-dot"></span>${repo.mode==='IndexedDB'?'已在本机就绪':repo.mode}</div></header><main id="main" tabindex="-1">${r==='read'?renderReading():r==='words'?renderWords():r==='notebook'?renderNotebook():r==='history'?renderHistory():renderSettings()}</main><footer class="app-footer"><span>学习数据只留在你的浏览器中</span><button data-action="backup">导出完整备份 ${icon('download')}</button></footer></div>`;
  if(r==='read'){const current=article();if(current)queueMicrotask(()=>{void activateReading(current,(w,c)=>resolver.lookup(w,c).senses.some(x=>x.source==='user'));if(route()==='read'&&article()?.id===current.id)void prepareReading(current,(word,context)=>resolver.lookup(word,context).senses.some(x=>(x.source==='user'||personal(x.id))&&!x.zh.startsWith('释义待补充')),liveUI);});}
}
function heading(title:string,description:string,actions=''){return `<div class="page-heading"><div><h1>${title}</h1><p>${description}</p></div>${actions?`<div class="heading-actions">${actions}</div>`:''}</div>`;}
function select(id:string,label:string,values:string[],value:string){return `<label class="select-field"><span>${label}</span><select id="${id}" aria-label="${label}">${values.map(v=>`<option ${v===value?'selected':''}>${esc(v)}</option>`).join('')}</select></label>`;}
function filteredArticles(){return articles().filter(a=>!activeSet||a.setId===activeSet);}
function article(){const matches=filteredArticles();return matches.find(a=>a.id===currentArticle)||matches[0];}
function renderReading(){
 const a=article();if(a)currentArticle=a.id;
 const matches=filteredArticles();
 return heading('阅读练习','从词汇表导入阅读，词义与段落译文在后台准备。',(a&&mergedArticleParts(a).length===5?button('split-merged','拆分为 5 篇','list','btn subtle'):'')+button('library','我的文章','folder','btn subtle')+`<a class="btn primary" href="#words">管理词汇表</a>`)+
 `<section class="reading-controls"><label class="select-field">词汇表<select id="active-set"><option value="">全部词汇表</option>${s().sets.map(t=>`<option value="${esc(t.id)}" ${activeSet===t.id?'selected':''}>${esc(t.name)}</option>`).join('')}</select></label></section>`+
 (!a?`<section class="empty reading-empty">${icon('search')}<h2>还没有阅读文章</h2><p>先在词汇库创建词汇表，导出生成请求，再导入生成好的文章。</p><a class="btn primary" href="#words">创建词汇表</a></section>`:
 `${generatedArticleNavigation(a)}<div class="reading-layout"><article class="reading-paper"><div class="article-meta"><span>${esc(a.topic)}</span><span>${a.length} · ${wordCount(a)} 词</span><span>${Math.max(1,Math.ceil(wordCount(a)/140))} 分钟阅读</span>${s().readArticles.includes(a.id)?'<span class="read-state">已读</span>':''}</div><h2 class="article-title" lang="en">${esc(a.title)}</h2><p class="article-subtitle">${esc(a.subtitle)}</p><div class="reading-tools"><span>${icon('info')}点击任意单词查词，标记词为本轮目标</span><div>${button('font-down','A−','','icon-btn','aria-label="缩小正文字号"')}${button('font-up','A＋','','icon-btn','aria-label="增大正文字号"')}${button('prepare-reading','准备缓存','','text-btn')}</div></div><div class="article-body" lang="en">${a.paragraphs.map((p,i)=>`<section class="paragraph"><p data-paragraph="${i}">${renderText(p.en,a,i)}</p><div class="paragraph-actions">${button('speak-paragraph','听整段','','text-btn',`data-p="${i}"`)}${button('stop-speech','停止朗读','','text-btn')}</div><details class="translation" lang="zh-CN"><summary>查看本段译文 ${icon('chevron')}</summary><p>${p.segments?p.segments.map(seg=>esc(seg.zh)+(seg.english?'<mark data-occurrence="'+esc(seg.occurrenceId||'')+'">（'+esc(seg.english)+'）</mark>':'')).join(''):esc(p.zh||cachedParagraph(p.en)||'后台正在准备译文，可继续阅读。')}</p></details></section>`).join('')}</div><div class="article-pagination"><span>${matches.findIndex(x=>x.id===a.id)+1} / ${matches.length} 篇匹配文章</span>${matches.length>1?button('next-article','下一篇阅读','arrow','btn subtle'):''}</div><p class="source-note">${esc(a.source)}。内容尚未独立语言审阅。</p></article><aside class="learning-rail"><div class="rail-title"><h2>本轮目标词</h2><span>${a.targets.length}</span></div><p class="rail-help">先在文章中相遇，再换个语境认识。</p><ul class="target-list">${a.targets.map((t,i)=>{const obj=senseById(t.senseId);return `<li><button data-action="target-word" data-sense="${esc(t.senseId)}" data-word="${esc(t.word)}"><span class="target-index">${String(i+1).padStart(2,'0')}</span><span><strong lang="en">${esc(t.word)}</strong><small>${esc(obj?.sense.pos||'')} · ${esc(obj&&(obj.sense.source==='user'||personal(obj.sense.id))?meaning(obj.sense):'点击直接查询')}</small></span>${saved(t.senseId)?icon('bookmark'):icon('plus')}</button></li>`}).join('')}</ul><div class="rail-note">${icon('book')}<h3>不急着记住每一个词</h3><p>先读懂这一段。需要时点开译文，把注意力留给词在句子里的意思。</p></div><div class="rail-progress"><span>本篇已收藏</span><strong>${a.targets.filter(t=>saved(t.senseId)).length}<small> / ${a.targets.length}</small></strong><div class="line-meter"><i style="width:${100*a.targets.filter(t=>saved(t.senseId)).length/Math.max(1,a.targets.length)}%"></i></div></div><p class="draft-note">本版为功能与数据候选版本。考试标签只展示已匹配的大纲依据。</p></aside></div>`);
}
function wordCount(a:Article){return (a.paragraphs.map(p=>p.en).join(' ').match(/\b[\w'-]+\b/g)||[]).length;}
function renderText(text:string,a:Article,p:number){
 const tokens=[...text.matchAll(/[A-Za-z]+(?:['’\-][A-Za-z]+)*/g)];let out='',last=0;
 for(let i=0;i<tokens.length;i++){
  const token=tokens[i];let word=token[0],end=token.index!+word.length;
  // Longest dictionary phrase, only across whitespace; punctuation remains a boundary.
  for(let n=Math.min(5,tokens.length-i);n>=2;n--){const group=tokens.slice(i,i+n),phrase=text.slice(token.index,group[n-1].index!+group[n-1][0].length);if(!/^[a-zA-Z'’ -]+$/.test(phrase))continue;const hasTarget=group.some(g=>a.targets.some(t=>normalized(t.word)===normalized(g[0])));const match=resolver.index.has(normalized(phrase))&&(s().custom.some(l=>normalized(l.lemma)===normalized(phrase))||!hasTarget||a.targets.some(t=>normalized(t.word)===normalized(phrase)));if(match){word=phrase;end=group[n-1].index!+group[n-1][0].length;i+=n-1;break;}}
  out+=esc(text.slice(last,token.index));const t=a.targets.find(t=>normalized(t.word)===normalized(word));
  out+=`<button class="word${t&&s().settings.highlight?' target-word':''}${t?.emphasized?' emphasized-word':''}" data-action="lookup" data-word="${esc(word)}" data-sense="${esc(t?.senseId||'')}" data-p="${p}" data-occurrence="${esc(a.occurrences?.find(o=>o.paragraph===p&&o.start===token.index&&o.end===end)?.id||'')}" lang="en" aria-label="查询 ${esc(word)}">${esc(word)}</button>`;last=end;
 }return out+esc(text.slice(last));
}
function stateLabel(senseId:string){const r=s().reviews.find(x=>x.id===senseId);return r?.mastered?'已掌握':r&&Date.parse(r.nextAt)<=Date.now()?'待复习':r?'学习中':'未测试';}
function searchBox(placeholder:string){return `<label class="search-box">${icon('search')}<input id="search" type="search" value="${esc(search)}" placeholder="${placeholder}" aria-label="${placeholder}"></label>`;}
function renderWords(){
 const active=s().sets.find(t=>t.id===activeSet),ids=new Set(active?.targets.map(t=>t.senseId)||[]),rows=lexemes().filter(l=>l.senses.some(x=>ids.has(x.id))).filter(l=>!search||l.lemma.toLowerCase().includes(search.toLowerCase())||l.senses.some(x=>meaning(x).includes(search)));
 return heading('词汇库','创建词汇表 → 导出生成请求 → 导入文章',button('import-words','新建词汇表','plus','btn primary'))+`<div class="collection-layout"><aside class="collections"><h2>我的词汇表</h2>${s().sets.map(t=>`<button class="collection ${activeSet===t.id?'active':''}" data-action="set" data-id="${esc(t.id)}">${icon('folder')}<span>${esc(t.name)}</span><em>${t.targets.length}</em></button>`).join('')||'<p class="muted">还没有词汇表</p>'}</aside><section class="word-workspace">${active?`<div class="section-heading"><h2>${esc(active.name)} · ${active.targets.length} 词</h2>${button('delete-set','删除词汇表','trash','text-btn')}</div><div class="button-row">${button('export-article-request','导出文章生成请求','download','btn primary')}${button('import-article','导入生成好的文章','upload','btn subtle')}${button('edit-set','编辑词义','edit','text-btn')}</div><div class="table-tools">${searchBox('搜索此词汇表')}</div><div class="table-wrap"><table><thead><tr><th>单词 / 短语</th><th>词义</th></tr></thead><tbody>${rows.map(l=>{const se=l.senses.find(x=>ids.has(x.id))!;return `<tr><td><button class="word-link" data-action="lookup" data-word="${esc(l.lemma)}" data-sense="${esc(se.id)}">${esc(l.lemma)}</button></td><td>${markdownInline(meaning(se))}</td></tr>`;}).join('')}</tbody></table></div>`:empty('从一张词汇表开始','点击“新建词汇表”，粘贴单词和词义，保留 Markdown 加粗与常考标记。')}</section></div>`;
}
function empty(title:string,desc:string,actions=''){return `<div class="empty">${icon('book')}<h2>${title}</h2><p>${desc}</p>${actions}</div>`;}
function renderNotebook(){
 let items=s().vocabulary.filter(v=>{const obj=senseById(v.senseId);return (!search||(obj?.lexeme.lemma+' '+v.form+' '+(obj?meaning(obj.sense):'')).toLowerCase().includes(search.toLowerCase()))&&(wordFilter==='all'||wordFilter==='due'&&due().some(r=>r.id===v.senseId)||wordFilter==='mastered'&&stateLabel(v.senseId)==='已掌握'||wordFilter==='learning'&&stateLabel(v.senseId)==='学习中');});
 items.sort(sort==='az'?(a,b)=>(getLex(a.lexemeId)?.lemma||a.form).localeCompare(getLex(b.lexemeId)?.lemma||b.form):(a,b)=>b.createdAt.localeCompare(a.createdAt));
 return heading('我的生词本','每一次收藏，都留着你与这个词相遇的语境。',(s().vocabulary.length?button('export-words','导出词汇','download','btn subtle'):'')+(due().length?button('review-due','复习到期词义 · '+due().length,'arrow','btn primary'):''))+
 `<div class="notebook-summary"><span><strong>${s().vocabulary.length}</strong> 已收藏义项</span><span><strong>${due().length}</strong> 到期待复习</span><span><strong>${s().reviews.filter(x=>x.mastered).length}</strong> 按规则已掌握</span></div><div class="table-tools">${searchBox('搜索单词、释义或实际词形')}<label><span class="sr-only">掌握状态</span><select id="word-filter"><option value="all" ${wordFilter==='all'?'selected':''}>全部状态</option><option value="due" ${wordFilter==='due'?'selected':''}>待复习</option><option value="learning" ${wordFilter==='learning'?'selected':''}>学习中</option><option value="mastered" ${wordFilter==='mastered'?'selected':''}>已掌握</option></select></label><label><span class="sr-only">排序</span><select id="sort"><option value="new" ${sort==='new'?'selected':''}>最近收藏</option><option value="az" ${sort==='az'?'selected':''}>字母顺序</option></select></label></div>${items.length?`<div class="batch-tools"><label><input type="checkbox" id="select-all" ${items.every(x=>selected.has(x.id))?'checked':''}>选择当前 ${items.length} 项</label><span>已选 ${selected.size} 项</span>${button('batch-set','加入目标集合','plus','text-btn')}${button('batch-edit','批量编辑释义','edit','text-btn')}${button('batch-delete','删除所选','trash','text-btn danger')}</div><div class="notebook-list">${items.map(v=>{const obj=senseById(v.senseId),se=obj?.sense;return `<article class="notebook-item"><label class="row-check"><input type="checkbox" data-select="${v.id}" aria-label="选择 ${esc(v.form)}" ${selected.has(v.id)?'checked':''}></label><div class="notebook-content"><div class="notebook-word"><button class="word-link" data-action="lookup" data-word="${esc(obj?.lexeme.lemma||v.form)}" data-sense="${esc(v.senseId)}" lang="en">${esc(obj?.lexeme.lemma||v.form)}</button><span class="state-tag">${stateLabel(v.senseId)}</span><span class="muted">${date(v.createdAt)}</span></div><p>${se?`<span class="pos">${esc(se.pos)}</span> ${markdownInline(meaning(se))}`:'原词典义项当前不可用；收藏信息仍保留。'}</p>${v.context?`<blockquote lang="en">${esc(v.context)}</blockquote>`:'<p class="muted">手动收藏 · 暂无来源语境</p>'}<small class="muted">${esc(articles().find(a=>a.id===v.articleId)?.title||'词典 / 手动录入')}${v.form!==obj?.lexeme.lemma?' · 实际词形 '+esc(v.form):''}</small></div><div class="row-actions">${button('edit-word','','edit','icon-btn',`data-sense="${esc(v.senseId)}" aria-label="编辑 ${esc(v.form)}"`)}${button('delete-word','','trash','icon-btn',`data-id="${v.id}" aria-label="删除 ${esc(v.form)}"`)}</div></article>`}).join('')}</div>`:empty(s().vocabulary.length?'没有匹配的收藏':'第一本词汇笔记，从一次好奇开始','阅读时点开一个词，选择当前义项，再把它收藏到这里。',`<a class="btn primary" href="#read">去阅读 ${icon('arrow')}</a>`)} `;
}
function renderHistory(){const attempts=s().attempts,first=[...new Map([...attempts].reverse().map(a=>[contextKey(a.question),a])).values()],correct=first.filter(a=>a.correct).length,weak=[...s().reviews].filter(r=>r.errors>0&&!r.mastered).sort((a,b)=>b.errors-a.errors);
 return heading('测试记录','看见具体的理解变化，把复习留给真正需要的义项。',(due().length?button('review-due','开始到期复习','arrow','btn primary'):''))+
 `<div class="stats-row"><div><span>首次提交题数</span><strong>${first.length}<small>题</small></strong></div><div><span>首次正确率</span><strong>${first.length?Math.round(100*correct/first.length)+'%':'—'}</strong></div><div><span>有效复习次数</span><strong>${attempts.filter(a=>a.effective).length}<small>次</small></strong></div><div><span>查询 / 已读文章</span><strong>${s().lookups}<small> / ${s().readArticles.length}</small></strong></div></div><div class="history-layout"><section><h2 class="section-title">最近的语境练习</h2>${attempts.length?`<div class="attempt-list">${[...attempts].reverse().slice(0,100).map(a=>`<button class="attempt-row" data-action="attempt" data-id="${a.id}"><span class="result-icon ${a.correct?'correct':'wrong'}">${icon(a.correct?'check':'close')}</span><span><strong lang="en">${esc(a.question.word)}</strong><small>${esc(a.question.context)}</small></span><span class="attempt-date">${date(a.submittedAt)}<small>${a.effective?'有效复习':'额外练习'}</small></span>${icon('chevron')}</button>`).join('')}</div>`:empty('还没有测试记录','完成一次跨语境测试后，这里会留下你的首次答案和逐项解析。',`<a class="btn subtle" href="#read">开始阅读</a>`)}</section><aside><h2 class="section-title">薄弱义项</h2>${weak.length?weak.map(r=>{const obj=senseById(r.id);return `<div class="weak-item"><strong lang="en">${esc(obj?.lexeme.lemma||r.id)}</strong><p>${esc(obj?.sense.zh||'原义项不可用')}</p><small>答错 ${r.errors} 次 · ${date(r.nextAt)} 复习</small></div>`}).join(''):'<div class="quiet-empty">暂无错误记录。新的测试结果会显示在这里。</div>'}<div class="review-rules"><h3>理解需要多次相遇</h3><p>默认间隔 1、3、7、14、30 天。相同义项在 24 小时内只计一次有效复习。</p><p>已掌握需至少跨 14 天、5 次答对的有效复习及 3 个语境。该规则不等同考试能力认证。</p></div></aside></div>`;
}
function renderSettings(){return heading('设置','把学习空间调整成适合你的样子。')+`<div class="settings-layout"><nav class="settings-index" aria-label="设置分区"><a href="#appearance" data-scroll="appearance">阅读与外观</a><a href="#storage" data-scroll="storage">数据与备份</a><a href="#generation" data-scroll="generation">阅读缓存与查询</a><a href="#dictionary" data-scroll="dictionary">学习内容与来源</a></nav><div class="settings-content"><section id="appearance" class="settings-section"><h2>阅读与外观</h2><div class="setting-row"><div><h3>颜色主题</h3><p>白天清晰阅读，夜间减少明亮背景。</p></div><select id="theme" aria-label="颜色主题">${[['light','暖白浅色'],['dark','深灰深色'],['system','跟随系统']].map(([v,l])=>`<option value="${v}" ${s().settings.theme===v?'selected':''}>${l}</option>`).join('')}</select></div><div class="setting-row"><div><h3>正文字号</h3><p>设置适用于英文阅读正文。</p></div><label><input id="font-size" type="range" min="16" max="26" value="${s().settings.fontSize}"> <output>${s().settings.fontSize}px</output></label></div></section><section id="storage" class="settings-section"><h2>数据与备份</h2><div class="storage-banner"><span class="status-dot"></span><div><strong>${repo.mode==='IndexedDB'?'本机存储可用':repo.mode}</strong><p>${esc(repo.detail)}</p></div></div><p class="setting-explanation">文件移动、隐私模式和浏览器清理可能影响本地数据。导出完整备份后，可在另一份 HTML 中恢复。凭据不会进入学习备份。</p><div class="button-row">${button('backup','导出完整备份','download','btn primary')}${button('restore','导入并预览备份','upload')}${button('previous','恢复上一保存快照','clock','btn subtle')}</div><div class="setting-row"><div><h3>清空学习数据</h3><p>清除收藏、个人修改和学习记录，内置内容仍在。</p></div>${button('reset','清空数据','trash','btn danger')}</div></section><section id="generation" class="settings-section"><h2>阅读缓存与查询</h2><p class="setting-explanation">接入的 AI 用于准备词义、段落译文及精准查询缓存。文章由你自行准备并批量导入，可边读边在后台缓存。</p><div class="provider-row"><span class="provider-symbol">${icon('book')}</span><div><strong>ChatGPT / 自定义模型 API</strong><p>使用你选择的服务和模型</p></div>${button('live-settings','连接或更换服务','arrow','btn subtle')}</div><p class="setting-explanation">已有阅读、词表、收藏和学习记录继续保留。直接查询需要网络；导入的个人释义仍可直接查看。</p></section><section id="dictionary" class="settings-section"><h2>学习内容与来源</h2><p class="release-status">${icon('info')}开发候选版，尚未达到正式首发门槛</p><dl class="data-facts"><div><dt>数据版本</dt><dd>${esc(data.manifest.version)}</dd></div><div><dt>离线候选词条</dt><dd>${data.manifest.headwords.toLocaleString()}（含同形不同词性）</dd></div><div><dt>内置阅读内容</dt><dd>不提供内置例文，仅使用你导入的文章</dd></div><div><dt>CET 全量覆盖</dt><dd>未通过；自动提取与词形对齐仍有未决项</dd></div><div><dt>雅思主题 2,000 词</dt><dd>已有 ${data.manifest.coverage.ieltsCandidates||0} 个自动主题选词候选；已精校 0，非官方词表</dd></div><div><dt>独立语言审阅</dt><dd>未执行；模型编写不等同人工精校</dd></div><div><dt>义项推荐准确率</dt><dd>尚无独立测试集测量结果</dd></div></dl>${data.manifest.sources.map(src=>`<div class="license-entry"><strong>${esc(src.name)}</strong><p>${esc(src.version)} · ${esc(src.license)}</p>${src.url?`<a href="${esc(src.url)}" target="_blank" rel="noopener noreferrer">查看原始来源 ${icon('arrow')}</a>`:''}</div>`).join('')}<p class="setting-explanation">程序源码 MIT。词典、派生词典和原创学习数据单独遵循 CC BY-SA 3.0；原始 TEI、许可及修改说明附在交付包中。未注明地区的 IPA 不归为英式或美式。</p></section></div></div>`;}
function closeOverlay(){overlay.querySelector('dialog')?.close();overlay.innerHTML='';const word=focusReturn?.dataset.word;const target=focusReturn?.isConnected?focusReturn:word?app.querySelector<HTMLElement>('[data-word="'+CSS.escape(word)+'"]'):document.getElementById('main');target?.focus({preventScroll:true});focusReturn=null;}
function modal(title:string,body:string,wide=false){closeOverlay();focusReturn=document.activeElement as HTMLElement;overlay.innerHTML=`<dialog class="modal${wide?' wide':''}" aria-labelledby="dialog-title"><div class="modal-head"><h2 id="dialog-title">${title}</h2>${button('close','','close','icon-btn','aria-label="关闭窗口"')}</div><div class="modal-body">${body}</div></dialog>`;const dialog=overlay.querySelector('dialog')!;dialog.showModal();dialog.addEventListener('cancel',e=>{e.preventDefault();closeOverlay()});dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if((e as MouseEvent).clientX<r.left||(e as MouseEvent).clientX>r.right||(e as MouseEvent).clientY<r.top||(e as MouseEvent).clientY>r.bottom)closeOverlay();}});}
async function showLookup(word:string,context='',annotated='',target=false,anchor?:HTMLElement){
 context=contextForWordNode(anchor,context);
 const own=resolver.lookup(word,context).senses.find(x=>(x.source==='user'||personal(x.id))&&!x.zh.startsWith('释义待补充'));
 if(!own){const found=await showLiveLookup(word,context,liveUI,async lexeme=>{const se=lexeme.senses[0];if(!await change(d=>{d.custom.push(lexeme);d.vocabulary.push({id:'v-'+se.id,lexemeId:lexeme.id,form:word,senseId:se.id,articleId:article()?.id||'',context,createdAt:now()});},'查询结果已收藏'))throw Error('收藏未能保存');resolver=new RuleSenseResolver(lexemes(),data.content.forms);});if(found)await change(d=>{d.lookups++;});return;}

 closeOverlay();focusReturn=anchor||document.activeElement as HTMLElement;
 const result=resolver.lookup(word,context,annotated);let active=result.senses[0]?.id;
 await change(d=>{d.lookups++});
 function draw(){const se=result.senses.find(x=>x.id===active),lex=result.candidates.find(l=>l.senses.some(x=>x.id===active)),full=target||result.ambiguous;
 overlay.innerHTML=`<section class="word-card ${full?'full':''}" role="dialog" aria-modal="false" aria-label="${esc(word)} 的词义"><div class="word-card-head"><div><span class="form-label">${lex&&normalized(word)!==normalized(lex.lemma)?esc(word)+' → 词元':''}</span><h2 lang="en">${esc(lex?.lemma||word)}</h2></div>${button('close','','close','icon-btn','aria-label="关闭词义卡"')}</div>${lex?`<p class="ipa" lang="en">${se&&personal(se.id)?.ipa?'个人 IPA '+esc(personal(se.id)!.ipa)+' · 原始来源：':''}${lex.ipa.uk?'英 '+esc(lex.ipa.uk)+' ':''}${lex.ipa.us?'美 '+esc(lex.ipa.us):''}${lex.ipa.other?.length?'IPA（来源未注明地区） '+esc(lex.ipa.other.slice(0,2).join(' · ')):!lex.ipa.uk&&!lex.ipa.us?'IPA 暂缺':''}</p>`:''}${se?`<div class="sense-heading"><span class="pos">${esc(se.pos)}</span><span class="tag">${result.recommended===se.id?'语境推荐':'常见义项'}</span></div><div class="sense-zh user-meaning">${markdownHTML(meaning(se))}</div>${full?`<p class="sense-en" lang="en">${esc(personal(se.id)?.en||se.en||'英文释义暂缺')}</p>`:''}${result.senses.length>1?`<label class="sense-picker">切换义项<select id="sense-picker">${result.senses.map(x=>`<option value="${esc(x.id)}" ${x.id===active?'selected':''}>${esc(x.pos+' · '+meaning(x).slice(0,65))}</option>`).join('')}</select></label>`:''}${context?`<blockquote lang="en">${esc(context)}</blockquote>`:''}<p class="resolve-reason">${esc(result.reason)}</p>${lex?.cet?`<span class="tag">${lex.cet} 大纲映射候选</span>`:''}<p class="quality-label">${esc(personal(se.id)?'含个人修改':se.status)}</p><div class="button-row">${button('speak-word','听发音','','btn subtle',`data-text="${esc(word)}"`)}${button('save-word',saved(se.id)?'已收藏此义项':'收藏此义项','bookmark','btn primary',`data-sense="${esc(se.id)}" data-word="${esc(word)}" data-context="${esc(context)}"`)}${button('edit-word','编辑','edit','btn subtle',`data-sense="${esc(se.id)}"`)}</div>`:`${button('speak-word','听发音','','btn subtle',`data-text="${esc(word)}"`)}<p class="sense-zh">暂未收录这个词</p><p class="resolve-reason">不自动补写释义。你可以将它添加为自定义词条。</p>${button('add-word','添加自定义词条','plus','btn primary',`data-word="${esc(word)}"`)}`}</section>`;
 const card=overlay.querySelector<HTMLElement>('.word-card')!;if(innerWidth>760){const r=anchor?.getBoundingClientRect();card.style.top=Math.min(Math.max(80,r?r.bottom+12:170),Math.max(80,innerHeight-card.offsetHeight-16))+'px';card.style.left=Math.min(Math.max(16,r?r.left:innerWidth/2-200),innerWidth-card.offsetWidth-16)+'px';}card.querySelector('button')?.focus({preventScroll:true});card.querySelector('#sense-picker')?.addEventListener('change',e=>{active=(e.target as HTMLSelectElement).value;draw();});}
 draw();
}
async function saveSense(senseId:string,form:string,context=''){const obj=senseById(senseId);if(!obj)return;const old=s().vocabulary.find(x=>x.senseId===senseId);if(old){announce('这个义项已在生词本中');return;}const a=article();if(await change(d=>d.vocabulary.push({id:'v-'+senseId,lexemeId:obj.lexeme.id,form:form||obj.lexeme.lemma,senseId,articleId:context&&a?a.id:'',context,createdAt:now()}),'已收藏到生词本')){render();const b=overlay.querySelector<HTMLButtonElement>('[data-action="save-word"]');if(b)b.innerHTML=icon('bookmark')+'已收藏此义项';}}
function editSense(id:string){const obj=senseById(id);if(!obj)return;const old=personal(id);modal('编辑个人释义',`<p class="modal-intro">修改仅保存为个人覆盖层，不改变原词典。原义项：<strong lang="en">${esc(obj.lexeme.lemma)}</strong></p><form id="edit-form"><label>中文释义<textarea name="zh" required maxlength="3000">${esc(old?.zh||obj.sense.zh)}</textarea></label><label>英文释义<textarea name="en" maxlength="6000">${esc(old?.en||obj.sense.en)}</textarea></label><label>个人 IPA（注明地区）<input name="ipa" value="${esc(old?.ipa||'')}" maxlength="300" placeholder="缺少可靠来源时可留空"></label><p class="source-note">原始中文：${esc(obj.sense.zh)}</p><div class="modal-actions">${button('close','取消','','btn subtle')}<button class="btn primary" type="submit">保存个人修改</button></div></form>`);overlay.querySelector('form')!.addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.target as HTMLFormElement);if(await change(d=>{d.overrides=d.overrides.filter(x=>x.senseId!==id);d.overrides.push({id:'override-'+id,lexemeId:obj.lexeme.id,senseId:id,zh:String(f.get('zh')).trim(),en:String(f.get('en')).trim(),ipa:String(f.get('ipa')).trim(),updatedAt:now(),previous:old?.zh||obj.sense.zh});},'个人修改已保存')){closeOverlay();render();}});}
function addWord(prefill=''){modal('添加词汇',`<form id="add-form"><label>英文词元<input name="word" value="${esc(prefill)}" required maxlength="100" pattern="[A-Za-z][A-Za-z '\u2019-]*" placeholder="例如 adapt"></label><label>中文释义（未收录词需手动填写）<textarea name="zh" maxlength="3000" placeholder="保留自己的理解，不自动编造释义"></textarea></label><label>英文释义（可选）<textarea name="en" maxlength="6000"></textarea></label><div class="modal-actions">${button('close','取消','','btn subtle')}<button type="submit" class="btn primary">添加并收藏</button></div></form>`);overlay.querySelector('form')!.addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.target as HTMLFormElement),word=String(f.get('word')).trim(),zh=String(f.get('zh')).trim(),en=String(f.get('en')).trim();const result=resolver.lookup(word);if(result.senses.length){closeOverlay();await showLookup(word,'','',true);return;}if(!zh){announce('未收录词需要你填写中文释义');return;}const l:Lexeme={id:'custom-'+uid(),lemma:word,ipa:{},senses:[{id:'custom-s-'+uid(),pos:'未注明',en,zh,source:'user',status:'自定义词条'}]};if(await change(d=>{d.custom.push(l);d.vocabulary.push({id:'v-'+l.senses[0].id,lexemeId:l.id,form:word,senseId:l.senses[0].id,articleId:'',context:'',createdAt:now()});},'自定义词条已收藏')){resolver=new RuleSenseResolver(lexemes(),data.content.forms);closeOverlay();render();}});}
function editBatch(ids:string[]){const entries=[...new Set(ids)].map(senseById).filter((x):x is NonNullable<typeof x>=>!!x);if(!entries.length){announce('请先选择要编辑的学习义项');return;}if(entries.length>200){announce('批量编辑每次最多 200 项，请缩小选择范围');return;}modal('批量编辑个人释义',`<p class="modal-intro">将编辑 ${entries.length} 个义项。所有更改一次保存为个人覆盖层，原词典保留。</p><form id="batch-form">${entries.map(x=>`<label><strong lang="en">${esc(x.lexeme.lemma)}</strong> · ${esc(x.sense.pos)}<textarea name="${esc(x.sense.id)}" required maxlength="3000">${esc(meaning(x.sense))}</textarea></label>`).join('')}<div class="modal-actions">${button('close','取消','','btn subtle')}<button type="submit" class="btn primary">保存 ${entries.length} 个义项</button></div></form>`,true);overlay.querySelector('form')!.addEventListener('submit',async e=>{e.preventDefault();const form=new FormData(e.target as HTMLFormElement);if(await change(d=>{for(const x of entries){const old=personal(x.sense.id);d.overrides=d.overrides.filter(o=>o.senseId!==x.sense.id);d.overrides.push({id:'override-'+x.sense.id,lexemeId:x.lexeme.id,senseId:x.sense.id,zh:String(form.get(x.sense.id)).trim(),en:old?.en||x.sense.en,ipa:old?.ipa||'',updatedAt:now(),previous:old?.zh||x.sense.zh});}},'批量个人释义已保存')){closeOverlay();render();}});}
function download(name:string,content:string,type='application/json'){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);}
async function exportBackup(){download('ContextFlow-完整备份-'+new Date().toISOString().slice(0,10)+'.json',JSON.stringify(await backupEnvelope(s()),null,2));announce('已生成完整备份，请保留下载文件');}
function pickFile(accept:string,callback:(text:string,name:string)=>Promise<void>|void){const input=document.createElement('input');input.type='file';input.accept=accept;input.onchange=async()=>{const file=input.files?.[0];if(!file)return;if(file.size>30*1024*1024){announce('文件超过 30MB，请拆分后导入');return;}try{await callback(await file.text(),file.name);}catch(e){announce(e instanceof Error?e.message:'文件无法读取，未写入数据');}};input.click();}
function restoreBackup(){pickFile('.json',async text=>{const incoming=await readBackup(JSON.parse(text));const p=previewMerge(s(),incoming);const conflicts:string[]=[];for(const k of ['overrides','custom','vocabulary','sets','articles','questions','attempts','reviews'] as const){for(const x of incoming[k] as {id:string}[]){const old=(s()[k] as {id:string}[]).find(o=>o.id===x.id);if(old&&canonical(old)!==canonical(x))conflicts.push(`<details class="conflict"><summary>${esc(k+' · '+x.id)}</summary><div class="compare"><div><h4>当前保留</h4><pre>${esc(JSON.stringify(old,null,2))}</pre></div><div><h4>备份内容</h4><pre>${esc(JSON.stringify(x,null,2))}</pre></div></div></details>`);}}
 modal('备份导入预览',`<div class="import-counts"><span>新增 <strong>${p.added}</strong></span><span>重复 <strong>${p.duplicate}</strong></span><span>冲突 <strong>${p.conflicts}</strong></span><span>无效 <strong>0</strong></span></div><p>词典版本：${esc(incoming.dictionaryVersion)}。完整性校验通过。导入会在一次事务中完成。</p><p class="modal-intro">默认保留本机已有内容及个人释义。选用备份冲突内容时，将同时使用备份设置。</p><label class="check-label"><input id="prefer-incoming" type="checkbox">使用备份中的全部冲突内容和设置</label>${conflicts.join('')||'<p class="muted">没有需要选择的记录冲突。</p>'}<div class="modal-actions">${button('close','取消','','btn subtle')}${button('commit-restore','确认合并导入','','btn primary')}</div>`,true);overlay.querySelector('[data-action="commit-restore"]')!.addEventListener('click',async()=>{const prefer=overlay.querySelector<HTMLInputElement>('#prefer-incoming')!.checked;try{await repo.replace(mergeState(s(),incoming,prefer));resolver=new RuleSenseResolver(lexemes(),data.content.forms);closeOverlay();render();announce(`导入完成：新增 ${p.added} 条，冲突按选择处理`);}catch{announce('导入失败，事务已回滚，原有数据未被覆盖');}});
 });}
function newSet(targets:Target[]=[]){modal('新建目标集合',`<form id="set-form"><label>集合名称<input name="name" maxlength="100" required placeholder="例如：本周环境主题"></label><p>${targets.length?'将加入所选的 '+targets.length+' 个学习义项。':'创建后，可用批量导入或从生词本加入词汇。'}</p><div class="modal-actions">${button('close','取消','','btn subtle')}<button type="submit" class="btn primary">创建集合</button></div></form>`);overlay.querySelector('form')!.addEventListener('submit',async e=>{e.preventDefault();const name=String(new FormData(e.target as HTMLFormElement).get('name')).trim();if(!name)return;const id=uid();if(await change(d=>d.sets.push({id,name,targets,source:'用户创建',updatedAt:now()}),'目标集合已创建')){activeSet=id;closeOverlay();render();}});}
function importWords(){wordImport();}
function exportWords(){modal('导出生词本',`<p>JSON 保留实际词形、来源、上下文及个人修改。若要完整恢复历史和复习，请使用“完整备份”。</p><div class="export-options">${button('words-json','JSON 词汇数据','download')}${button('words-csv','CSV 表格（Excel）','download')}${button('words-txt','TXT 单词列表','download')}</div>`);for(const format of ['json','csv','txt'])overlay.querySelector('[data-action="words-'+format+'"]')!.addEventListener('click',()=>{const rows=s().vocabulary.map(v=>{const obj=senseById(v.senseId);return {...v,word:obj?.lexeme.lemma||v.form,zh:obj?meaning(obj.sense):'',en:obj?.sense.en||'',personal:personal(v.senseId)||null};});if(format==='json')download('ContextFlow-词汇.json',JSON.stringify(rows,null,2));else if(format==='csv')download('ContextFlow-词汇.csv','\uFEFF'+[['word','zh','en','form','context','sourceArticle','savedAt'],...rows.map(r=>[r.word,r.zh,r.en,r.form,r.context,r.articleId,r.createdAt])].map(row=>row.map(csvCell).join(',')).join('\r\n'),'text/csv;charset=utf-8');else download('ContextFlow-词汇.txt',rows.map(r=>r.word+'\t'+r.zh).join('\r\n'),'text/plain;charset=utf-8');closeOverlay();});}
function mergedArticleParts(a:Article){if(!a.id.startsWith('import'))return [];try{return parseArticles('# '+a.title+'\n'+a.paragraphs.map(p=>p.en).join('\n\n'),a.mode,'repair-'+a.id);}catch{return [];}}
async function splitMergedArticle(){const old=article();if(!old)return;const parts=mergedArticleParts(old);if(parts.length!==5){announce('未识别到五篇独立文章，请重新导入并检查识别结果');return;}const incoming=parts.map((a,i)=>({...a,id:i===0?old.id:a.id,batchId:'repaired-'+old.id,setId:old.setId,targets:old.targets.filter(t=>containsRequiredWord(a.paragraphs.map(p=>p.en).join(' '),t.word))}));if(await change(d=>{d.articles=d.articles.filter(a=>a.id!==old.id);d.articles.push(...incoming);},'已拆分为 5 篇独立阅读')){resetReadingPreparation();currentArticle=incoming[0].id;render();for(const a of incoming)void prepareReading(a,(w,c)=>resolver.lookup(w,c).senses.some(se=>se.source==='user'),liveUI);}}
function importArticle(){
 if(!s().sets.length){wordImport();return;}
 modal('批量导入阅读',`<section data-component="ArticleImport"><p class="modal-intro">支持 Article 1–5、第一篇、Markdown 各级标题、加粗标题和 JSON 文章数组；空行分段。也可选择多个文件。</p><form id="article-form"><label>所属词汇表<select name="set" required>${s().sets.map(t=>`<option value="${esc(t.id)}" ${t.id===activeSet?'selected':''}>${esc(t.name)}</option>`).join('')}</select></label><label>阅读内容<textarea name="text" rows="13" maxlength="500000" placeholder="# 第一篇标题&#10;English paragraphs…&#10;&#10;---&#10;&#10;# 第二篇标题&#10;English paragraphs…"></textarea></label><div class="button-row"><label class="btn subtle">选择多个文件<input id="article-files" type="file" multiple accept=".txt,.md,.markdown,.json" style="max-width:230px"></label></div><p id="article-import-status" role="status"></p><div class="modal-actions"><button type="submit" class="btn primary">导入并开始后台缓存</button></div></form></section>`,true);
 const form=overlay.querySelector<HTMLFormElement>('form')!,input=form.querySelector<HTMLTextAreaElement>('textarea')!,status=form.querySelector<HTMLElement>('[role="status"]')!;let loading=false;const preview=()=>{try{const parsed=parseArticles(input.value,exam,'preview');status.textContent='识别到 '+parsed.length+' 篇：'+parsed.map((a,i)=>(i+1)+'. '+a.title).join('；');}catch(e){status.textContent=(e as Error).message;}};input.oninput=preview;
 form.querySelector<HTMLInputElement>('#article-files')!.onchange=async event=>{loading=true;try{const files=[...(event.target as HTMLInputElement).files||[]];input.value=(await Promise.all(files.map(async file=>{const text=await file.text();if(/\.json$/i.test(file.name))return parseArticles(text,exam,'file').map(a=>'# '+a.title+'\n'+a.paragraphs.map(p=>p.en).join('\n\n')).join('\n\n---\n\n');return /^\s*#{1,6}\s/.test(text)?text:'# '+file.name.replace(/\.[^.]+$/,'')+'\n'+text;}))).join('\n\n---\n\n');preview();}catch(e){status.textContent=(e as Error).message;}finally{loading=false;}};

 form.onsubmit=async event=>{event.preventDefault();if(loading)return;try{const set=s().sets.find(t=>t.id===(new FormData(form).get('set')));if(!set)throw Error('请先选择词汇表');const incoming=parseArticles(input.value,exam,uid()).map(a=>({...a,setId:set.id,targets:set.targets.filter(t=>containsRequiredWord(a.paragraphs.map(p=>p.en).join(' '),t.word))}));const missing=incoming.map((a,i)=>({index:i+1,words:set.targets.filter(t=>!a.targets.some(found=>found.senseId===t.senseId)).map(t=>t.word)})).filter(x=>x.words.length);if(missing.length)throw Error('文章未覆盖所选词汇表：'+missing.map(x=>'第 '+x.index+' 篇缺少 '+x.words.join('、')).join('；'));const submit=form.querySelector<HTMLButtonElement>('[type="submit"]')!;submit.disabled=true;if(await change(d=>{d.articles.push(...incoming);d.settings.lastArticle=incoming[0].id;})){closeOverlay();currentArticle=incoming[0].id;topic='全部主题';length='全部长度';activeSet=set.id;location.hash='read';render();window.scrollTo(0,0);for(const item of incoming)void prepareReading(item,(word,context)=>resolver.lookup(word,context).senses.some(x=>(x.source==='user'||personal(x.id))&&!x.zh.startsWith('释义待补充')),liveUI);announce('已导入 '+incoming.length+' 篇阅读，正在后台准备缓存');}else submit.disabled=false;}catch(e){status.textContent=(e as Error).message;}};
}
function previewBundle(raw:unknown){const b=validateBundle(raw,data,s().custom);for(const q of b.questions){const existing=questions().find(x=>x.id===q.id);if(existing&&canonical(existing)!==canonical(q))throw Error('存在同 ID 但内容不同的题目，请给新版本使用新的稳定 ID。');}const conflicts=b.articles.filter(a=>articles().some(x=>x.id===a.id));modal('学习包预览',`<div class="import-counts"><span>文章 <strong>${b.articles.length}</strong></span><span>题目 <strong>${b.questions.length}</strong></span><span>重复文章 <strong>${conflicts.length}</strong></span></div><p>结构、目标词出现、题目选项和文章引用已检查。语言自然度、义项搭配、译文对应和答案唯一性仍需人工审阅。</p>${b.articles.map(a=>`<details open><summary>${esc(a.title)} · ${a.targets.length} 个目标义项</summary>${a.paragraphs.map(p=>`<p lang="en">${esc(p.en)}</p><p class="muted">${esc(p.zh)}</p>`).join('')}</details>`).join('')}<details><summary>查看题目与答案</summary>${b.questions.map(q=>`<p>${esc(q.context)}</p><ol>${q.options.map((x,i)=>`<li>${esc(x)}${q.answer===i?' ✓':''}<p class="muted">${esc(q.explanations[i])}</p></li>`).join('')}</ol>`).join('')}</details><label class="check-label"><input type="checkbox" id="approve-content">我已审阅内容，同意保存（同 ID 相同题目与已有文章跳过）</label><div class="modal-actions">${button('close','取消','','btn subtle')}${button('commit-bundle','保存到文章库','','btn primary','disabled')}</div>`,true);overlay.querySelector('#approve-content')!.addEventListener('change',e=>{overlay.querySelector<HTMLButtonElement>('[data-action="commit-bundle"]')!.disabled=!(e.target as HTMLInputElement).checked;});overlay.querySelector('[data-action="commit-bundle"]')!.addEventListener('click',async()=>{const existingA=new Set(articles().map(a=>a.id)),existingQ=new Set(questions().map(q=>q.id));const incomingA=b.articles.filter(a=>!existingA.has(a.id)),incomingQ=b.questions.filter(q=>!existingQ.has(q.id));if(await change(d=>{d.articles.push(...incomingA);d.questions.push(...incomingQ);},`已导入 ${incomingA.length} 篇文章与 ${incomingQ.length} 道题`)){closeOverlay();if(incomingA[0]){exam=incomingA[0].mode;topic='全部主题';length='全部长度';activeSet='';currentArticle=incomingA[0].id;location.hash='read';}render();for(const item of incomingA)void prepareReading(item,(w,c)=>resolver.lookup(w,c).senses.some(x=>(x.source==='user'||personal(x.id))&&!x.zh.startsWith('释义待补充')),liveUI);}});}
function library(){modal('文章库',`<p class="modal-intro">你导入的阅读文章，可在词汇表中继续添加。</p><div class="library-list">${articles().map(a=>`<button data-action="open-article" data-id="${a.id}"><span class="library-topic">${esc(a.topic)}</span><span><strong lang="en">${esc(a.title)}</strong><small>${esc(a.mode)} · ${a.length} · ${wordCount(a)} 词${s().readArticles.includes(a.id)?' · 已读':''}</small></span>${icon('arrow')}</button>`).join('')}</div>`,true);}
function startQuiz(isDue=false){const a=article();const targetIds=isDue?new Set(due().map(r=>r.id)):new Set(a?.targets.map(t=>t.senseId)||[]);const attempted=new Set(s().attempts.map(x=>contextKey(x.question)));const pool=[...new Map(questions().filter(q=>targetIds.has(q.senseId)&&(isDue||a?.questionIds.includes(q.id))).map(q=>[contextKey(q),q])).values()];const unseen=pool.filter(q=>!attempted.has(contextKey(q)));
 if(!pool.length||(!isDue&&!unseen.length)){modal(isDue?'到期复习':'跨语境测试',`<p>${isDue&&!targetIds.size?'目前没有到期的复习义项。按实际复习时间安排，今天可以继续阅读。':'当前没有未练习的新题。已有题库不足以继续提供新语境，不会通过调整选项伪装成新题。'}</p><p class="muted">可导入包含新语境的学习包；旧题仍可查看首次答案与解析。</p><div class="modal-actions">${button('close','返回阅读','','btn primary')}${button('import-article','导入学习包','upload','btn subtle')}</div>`);return;}
 const chosen:Question[]=[];const ids=new Set<string>();for(const q of (isDue?[...pool].sort((a,b)=>Number(attempted.has(contextKey(a)))-Number(attempted.has(contextKey(b)))||(s().attempts.filter(x=>contextKey(x.question)===contextKey(a)).at(-1)?.submittedAt||'').localeCompare(s().attempts.filter(x=>contextKey(x.question)===contextKey(b)).at(-1)?.submittedAt||'')):unseen)){if(!ids.has(q.senseId)){chosen.push(q);ids.add(q.senseId);}if(chosen.length>=10)break;}
 quiz={questions:chosen,index:0,answers:new Map(),submitted:false,selected:-1,article:a?.id,isReview:isDue};if(a&&!isDue)void change(d=>{if(!d.readArticles.includes(a.id))d.readArticles.push(a.id)});drawQuiz();}
function drawQuiz(){if(!quiz)return;const state=quiz,q=state.questions[state.index];const attemptId=state.answers.get(q.id),attempt=s().attempts.find(a=>a.id===attemptId);const selectedIndex=attempt?.selected??state.selected;const practised=s().attempts.some(a=>contextKey(a.question)===contextKey(q)&&a.id!==attemptId);modal('跨语境测试',`<div class="quiz-meta"><span>${state.index+1} / ${state.questions.length}</span><span>${state.isReview?'到期复习 · '+(practised?'旧题（不算新题）':'未练习语境'):'英文理解 · 未练习语境'}</span></div><div class="quiz-track"><i style="width:${100*state.index/state.questions.length}%"></i></div><p class="quiz-context" lang="en">${esc(q.context).replace(new RegExp('\\b'+q.word+'\\b','gi'),'<mark>$&</mark>')}</p><h3 class="quiz-prompt" lang="en">${esc(q.prompt)}</h3><div class="quiz-options">${q.options.map((o,i)=>`<button data-action="answer" data-index="${i}" ${attempt?'disabled':''} aria-pressed="${selectedIndex===i}" class="quiz-option${selectedIndex===i?' chosen':''}${attempt&&q.answer===i?' answer-correct':''}${attempt&&selectedIndex===i&&!attempt.correct?' answer-wrong':''}"><span>${'ABCD'[i]}</span><span lang="en">${esc(o)}</span>${attempt&&q.answer===i?icon('check'):''}</button>`).join('')}</div>${attempt?`<div class="quiz-explanation"><h3>${attempt.correct?'理解正确':'再看一次这个义项'}</h3><p>${attempt.effective?'已记录本次有效复习。':'首次成绩已记录；该义项距上次有效复习不足 24 小时，本次为额外练习。'}</p>${q.explanations.map((x,i)=>`<p><strong>${'ABCD'[i]}</strong> ${esc(x)}</p>`).join('')}</div>`:'<p class="quiz-hint">提交后显示中文解析。首次提交确定成绩。</p>'}<div class="modal-actions"><span class="muted">${data.manifest.status.split(' · ')[0]}</span>${attempt?button('quiz-next',state.index+1===state.questions.length?'查看本轮结果':'下一题','arrow','btn primary'):button('submit-answer','提交答案','','btn primary',selectedIndex<0?'disabled':'')}</div>`,true);}
async function submitAnswer(){if(!quiz||quiz.selected<0||quiz.submitted)return;quiz.submitted=true;const q=quiz.questions[quiz.index];const previous=s().attempts.find(a=>contextKey(a.question)===contextKey(q));if(previous&&!quiz.isReview){quiz.answers.set(q.id,previous.id);drawQuiz();return;}const id=uid(),chosen=quiz.selected,result=reviewAfter(s().reviews.find(x=>x.id===q.senseId),q,chosen===q.answer);
 if(await change(d=>{d.attempts.push({id,question:structuredClone(q),selected:chosen,correct:chosen===q.answer,submittedAt:now(),effective:result.effective,kind:quiz!.isReview?'review':'initial'});d.reviews=d.reviews.filter(x=>x.id!==q.senseId);d.reviews.push(result.state);})){quiz.answers.set(q.id,id);render();drawQuiz();}else quiz.submitted=false;}
function nextQuiz(){if(!quiz)return;if(quiz.index+1<quiz.questions.length){quiz.index++;quiz.selected=-1;quiz.submitted=false;drawQuiz();}else{const attempts=s().attempts.filter(a=>[...quiz!.answers.values()].includes(a.id)),correct=attempts.filter(a=>a.correct).length;modal('本轮练习完成',`<div class="quiz-result"><span class="result-icon correct">${icon('check')}</span><h3>又多了一次语境里的相遇</h3><p>完成 ${attempts.length} 题，答对 ${correct} 题。</p><p class="muted">一次答对记录本次表现，掌握状态需经过多次间隔复习。</p></div><div class="modal-actions">${button('close','继续阅读','','btn subtle')}<a class="btn primary" href="#history" data-action="close">查看测试记录 ${icon('arrow')}</a></div>`);quiz=undefined;render();}}
function showAttempt(id:string){const a=s().attempts.find(a=>a.id===id);if(!a)return;const q=a.question;modal('首次答题记录',`<p class="quiz-context" lang="en">${esc(q.context)}</p><p lang="en">${esc(q.prompt)}</p>${q.options.map((o,i)=>`<div class="record-option ${i===q.answer?'correct':''}"><strong>${'ABCD'[i]}</strong> <span lang="en">${esc(o)}</span> ${i===a.selected?'（你的首次答案）':''}${i===q.answer?'（正确项）':''}<p>${esc(q.explanations[i])}</p></div>`).join('')}<p class="muted">${new Date(a.submittedAt).toLocaleString('zh-CN')} · ${a.effective?'有效复习':'额外练习'}</p>`,true);}
function exportArticleRequest(){const set=s().sets.find(t=>t.id===activeSet);if(!set||!set.targets.length){announce('请先创建并选择有单词的词汇表');return;}const words=set.targets.map(t=>{const se=senseById(t.senseId)?.sense;return `- ${t.emphasized?'**'+t.word+'**':t.word}：${se?meaning(se):'未提供词义'}`;}).join('\n');download(set.name+'-文章生成请求.md',`# 阅读文章生成请求\n\n请使用以下词汇及指定中文词义，创作 5 篇内容不同、自然连贯的英文阅读文章。每一篇英文正文都必须完整包含所有单词或短语，保持原词形；加粗与常考词义优先，不擅自替换用户释义。可根据词量调整篇幅。\n\n只输出英文标题和英文段落，不附加词表、中文翻译、题目或说明。每篇使用 # 标题，文章之间用单独一行 --- 分隔，段落之间空一行，以便批量导入阅读工具。\n\n## 词汇表：${set.name}\n${words}\n`,'text/markdown;charset=utf-8');}
function wordImport(){
 modal('新建词汇表',`<p>保留 Markdown 词义、加粗与常考标记；你提供的最新词义优先。</p><form id="word-import-form"><label>词表名称<input name="name" value="我的词表" required></label><label>单词与词义<textarea name="words" rows="10" required placeholder="**in that**：因为，由于，在于"></textarea></label><p id="word-import-error" role="alert"></p><div class="modal-actions"><button class="btn primary" type="submit">保存词表</button></div></form>`,true);
 overlay.querySelector('form')!.onsubmit=async e=>{e.preventDefault();try{const f=new FormData(e.target as HTMLFormElement),raw=String(f.get('words')),parsed=parseGenerationWords(raw);if(!parsed.words.length||parsed.overLimit||parsed.invalid.length)throw Error('请检查词表，单次最多 200 个有效单词或短语');const setId=uid(),custom:Lexeme[]=[],targets:Target[]=[];for(const w of parsed.words){const existing=!w.zh?resolver.lookup(w.word).senses.find(x=>(x.source==='user'||personal(x.id))&&!x.zh.startsWith('释义待补充')):undefined;if(existing){targets.push({word:w.word,senseId:existing.id,emphasized:w.emphasized});continue;}const id='user-s-'+uid();custom.push({id:'user-'+uid(),lemma:w.word,ipa:{},senses:[{id,pos:'未注明',en:'',zh:w.zh||'释义待补充（用户导入）',source:'user',status:'用户导入'}]});targets.push({word:w.word,senseId:id,emphasized:w.emphasized});}if(await change(d=>{d.custom.push(...custom);d.sets.push({id:setId,name:String(f.get('name')),targets,source:'用户词表',markdown:raw,updatedAt:now()});})){resolver=new RuleSenseResolver(lexemes(),data.content.forms);closeOverlay();activeSet=setId;render();announce('词表已保存，采用你最新导入的词义');}}catch(error){overlay.querySelector('#word-import-error')!.textContent=(error as Error).message;}};
}
function generatedArticleNavigation(a:Article){const match=a.id.match(/^((?:generated|import-batch)-.+)-\d+$/);const siblings=a.batchId?articles().filter(x=>x.batchId===a.batchId):match?articles().filter(x=>x.id.startsWith(match[1]+'-')):[];if(siblings.length<2)return '';return `<nav class="generated-navigation" aria-label="本批阅读文章"><span>本批阅读 · ${siblings.length} 篇</span><div>${siblings.map((x,i)=>button('open-generated',`第 ${i+1} 篇`,'','btn subtle',`data-id="${esc(x.id)}" ${x.id===a.id?'aria-current="true"':''}`)).join('')}</div></nav>`;}


async function deleteItems(ids:string[]){const removed=s().vocabulary.filter(v=>ids.includes(v.id));if(!removed.length){announce('请先选择要删除的词义');return;}if(await change(d=>{d.vocabulary=d.vocabulary.filter(v=>!ids.includes(v.id));})){selected.clear();render();announce(`已删除 ${removed.length} 个收藏义项`,()=>{void change(d=>{const existing=new Set(d.vocabulary.map(v=>v.id));d.vocabulary.push(...removed.filter(v=>!existing.has(v.id)));},'已恢复删除的收藏').then(()=>render());});}}
document.addEventListener('click',async e=>{const target=e.target as HTMLElement;const action=target.closest<HTMLElement>('[data-action]');if(!action){if(overlay.querySelector('.word-card')&&!target.closest('.word-card'))closeOverlay();return;}const name=action.dataset.action!;const a=article();try{
 switch(name){
 case 'close':closeOverlay();break;
 case 'prepare-reading':if(a)void prepareReading(a,(word,context)=>resolver.lookup(word,context).senses.some(x=>(x.source==='user'||personal(x.id))&&!x.zh.startsWith('释义待补充')),liveUI,true);break;
 case 'live-settings':void showServiceSettings(liveUI);break;
 case 'direct-query':modal('直接查询',`<form id="direct-query-form"><label>英文单词或短语<input name="word" required maxlength="100" placeholder="例如 in that"></label><div class="modal-actions"><button class="btn primary" type="submit">查询</button></div></form>`);overlay.querySelector('form')!.addEventListener('submit',e=>{e.preventDefault();const word=String(new FormData(e.target as HTMLFormElement).get('word')).trim();if(word)void showLookup(word);});break;
 case 'speak-word':case 'speak-selection':speakEnglish(action.dataset.text||selectedReadingText);break;
 case 'speak-paragraph':speakEnglish(a?.paragraphs[Number(action.dataset.p)]?.en||'');break;
 case 'stop-speech':stopSpeech();break;
 case 'inspect-selection':inspectSelection();break;
 case 'translate-selection':translateSelection();break;
 case 'theme':await change(d=>{d.settings.theme=d.settings.theme==='dark'?'light':'dark'});render();break;
 case 'exam':exam=action.dataset.value as Mode;currentArticle='';await change(d=>{d.settings.mode=exam});render();break;
 case 'font-down':case 'font-up':await change(d=>{d.settings.fontSize=Math.min(26,Math.max(16,d.settings.fontSize+(name==='font-up'?1:-1)))});applyTheme();break;
 case 'highlight':await change(d=>{d.settings.highlight=!d.settings.highlight});render();break;
 case 'clear-filter':topic='全部主题';length='全部长度';activeSet='';render();break;
 case 'next-article':{const matches=filteredArticles();currentArticle=matches[(matches.findIndex(x=>x.id===currentArticle)+1)%matches.length]?.id||'';await change(d=>{d.settings.lastArticle=currentArticle});render();document.getElementById('main')?.scrollIntoView();break;}
 case 'lookup':{const context=action.dataset.context||a?.paragraphs[Number(action.dataset.p)]?.en||'';await showLookup(action.dataset.word!,context,action.dataset.sense||'',!!action.dataset.sense,action);break;}
 case 'target-word':await showLookup(action.dataset.word!,a?.paragraphs.find(p=>p.en.toLowerCase().includes(action.dataset.word!.toLowerCase()))?.en||'',action.dataset.sense!,true,action);break;
 case 'save-word':await saveSense(action.dataset.sense!,action.dataset.word||'',action.dataset.context||'');break;
 case 'edit-word':editSense(action.dataset.sense!);break;
 case 'add-word':addWord(action.dataset.word||'');break;
 case 'new-set':wordImport();break;
 case 'set':activeSet=action.dataset.id!;render();break;
 case 'delete-set':if(activeSet&&await change(d=>{d.sets=d.sets.filter(t=>t.id!==activeSet)},'集合已删除')){activeSet='';render();}break;
 case 'export-markdown':{const set=s().sets.find(t=>t.id===activeSet);if(set?.markdown)download('ContextFlow-原始词表.md',set.markdown,'text/markdown;charset=utf-8');break;}
 case 'import-words':importWords();break;
 case 'export-words':exportWords();break;
 case 'backup':await exportBackup();break;
 case 'restore':restoreBackup();break;
 case 'delete-word':await deleteItems([action.dataset.id!]);break;
 case 'batch-edit':editBatch(s().vocabulary.filter(v=>selected.has(v.id)).map(v=>v.senseId));break;
 case 'edit-set':editBatch(s().sets.find(t=>t.id===activeSet)?.targets.map(t=>t.senseId)||[]);break;
 case 'batch-delete':await deleteItems([...selected]);break;
 case 'batch-set':{const targets=s().vocabulary.filter(v=>selected.has(v.id)).map(v=>({word:getLex(v.lexemeId)?.lemma||v.form,senseId:v.senseId}));if(!targets.length)announce('先选择要加入训练的收藏义项');else newSet(targets);break;}
 case 'library':library();break;
 case 'open-generated':{const chosen=articles().find(x=>x.id===action.dataset.id);if(chosen){if(!await change(d=>{d.settings.lastArticle=chosen.id;d.settings.mode=chosen.mode}))break;exam=chosen.mode;topic='全部主题';length='全部长度';activeSet=chosen.setId||'';currentArticle=chosen.id;location.hash='read';render();window.scrollTo(0,0);}break;}
 case 'open-article':{const chosen=articles().find(x=>x.id===action.dataset.id);if(chosen){exam=chosen.mode;topic='全部主题';length='全部长度';activeSet=chosen.setId||'';currentArticle=chosen.id;await change(d=>{d.settings.lastArticle=chosen.id;d.settings.mode=exam});closeOverlay();render();}break;}
 case 'import-article':importArticle();break;
 case 'split-merged':await splitMergedArticle();break;
 case 'export-article-request':exportArticleRequest();break;
 
 
 case 'start-quiz':startQuiz();break;
 case 'review-due':startQuiz(true);break;
 case 'answer':if(quiz&&!quiz.answers.has(quiz.questions[quiz.index].id)){quiz.selected=Number(action.dataset.index);drawQuiz();}break;
 case 'submit-answer':await submitAnswer();break;
 case 'quiz-next':nextQuiz();break;
 case 'attempt':showAttempt(action.dataset.id!);break;
 case 'previous':{const previous=await repo.previous();if(!previous){announce('当前没有可恢复的 IndexedDB 快照');break;}modal('恢复上一保存快照',`<p>快照时间：${new Date(previous.updatedAt).toLocaleString('zh-CN')}。恢复前建议先导出当前数据。</p><div class="modal-actions">${button('backup','导出当前备份','download','btn subtle')}${button('confirm-previous','恢复此快照','','btn primary')}</div>`);overlay.querySelector('[data-action="confirm-previous"]')!.addEventListener('click',async()=>{try{await repo.replace(previous);resolver=new RuleSenseResolver(lexemes(),data.content.forms);closeOverlay();render();announce('已恢复上一快照');}catch{announce('恢复失败，原有数据保留');}});break;}
 case 'reset':modal('清空本机学习数据',`<p>将清除 ${s().vocabulary.length} 个收藏、${s().attempts.length} 条答题及所有个人修改、导入文章和目标集合。建议先导出备份。</p><label>输入“清空”确认<input id="reset-confirm" autocomplete="off"></label><div class="modal-actions">${button('backup','先导出备份','download','btn subtle')}${button('confirm-reset','确认清空','','btn danger')}</div>`);overlay.querySelector('[data-action="confirm-reset"]')!.addEventListener('click',async()=>{if(overlay.querySelector<HTMLInputElement>('#reset-confirm')!.value!=='清空'){announce('请输入“清空”后再确认');return;}try{await repo.replace(initialState(data.manifest.version));resolver=new RuleSenseResolver(lexemes(),data.content.forms);activeSet='';selected.clear();clearLookupCache();clearTranslationCache();await clearReadingCache();resetReadingPreparation();closeOverlay();render();announce('已清空学习数据');}catch{announce('清空失败，数据未改变');}});break;
 }
 }catch(err){announce(err instanceof Error?err.message:'操作未完成，请重试');}
});
document.addEventListener('change',async e=>{const el=e.target as HTMLInputElement;if(el.id==='topic'){topic=el.value;currentArticle='';render();}else if(el.id==='length'){length=el.value;currentArticle='';render();}else if(el.id==='active-set'){activeSet=el.value;currentArticle='';render();}else if(el.id==='word-filter'){wordFilter=el.value;render();}else if(el.id==='sort'){sort=el.value;render();}else if(el.id==='theme'){await change(d=>{d.settings.theme=el.value as UserState['settings']['theme']});render();}else if(el.id==='font-size'){await change(d=>{d.settings.fontSize=Number(el.value)});render();}else if(el.dataset.select){if(el.checked)selected.add(el.dataset.select);else selected.delete(el.dataset.select);render();}else if(el.id==='select-all'){const inputs=app.querySelectorAll<HTMLInputElement>('[data-select]');for(const input of inputs){if(el.checked)selected.add(input.dataset.select!);else selected.delete(input.dataset.select!);}render();}});
document.addEventListener('input',e=>{const el=e.target as HTMLInputElement;if(el.id==='search'){search=el.value;const pos=el.selectionStart;render();const input=app.querySelector<HTMLInputElement>('#search');input?.focus();if(input&&input.type!=='search')input.setSelectionRange(pos,pos);}if(el.id==='font-size'){el.parentElement!.querySelector('output')!.textContent=el.value+'px';document.documentElement.style.setProperty('--reading-size',el.value+'px');}});
document.addEventListener('click',e=>{const link=(e.target as HTMLElement).closest<HTMLAnchorElement>('[data-scroll]');if(link){e.preventDefault();document.getElementById(link.dataset.scroll!)?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});}});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeOverlay();});
window.addEventListener('hashchange',()=>{closeOverlay();search='';wordFilter='all';selected.clear();render();document.getElementById('main')?.focus({preventScroll:true});window.scrollTo(0,0);});
window.addEventListener('resize',()=>{if(overlay.querySelector('.word-card'))closeOverlay();});
matchMedia('(prefers-color-scheme: dark)').addEventListener('change',applyTheme);
async function init(){await repo.init();if(!s().libraryReset015){await repo.commit(d=>{const kept=new Set([...d.vocabulary.map(v=>v.senseId),...d.attempts.map(a=>a.question.senseId)]);d.sets=[];d.custom=d.custom.filter(l=>l.senses.some(se=>kept.has(se.id)));d.libraryReset015=true;});}resolver=new RuleSenseResolver(lexemes(),data.content.forms);exam=s().settings.mode;currentArticle=s().settings.lastArticle||'article-1-1';render();if(repo.mode==='临时模式')announce(repo.detail);}
void init();

let selectedReadingText='';
function knownSelectionTranslation(text:string){const paragraphs=(article()?.paragraphs||[]).map(p=>({...p,zh:p.zh||cachedParagraph(p.en)}));const candidate=paragraphs.filter(p=>translationKey(text).includes(translationKey(p.en)));if(candidate.length&&candidate.every(p=>p.zh&&!p.zh.startsWith('本段未提供译文'))&&translationKey(candidate.map(p=>p.en).join(' '))===translationKey(text))return candidate.map(p=>p.zh).join('\n\n');return '';}
function inspectSelection(){const text=selectedReadingText;if(!text)return;const own=resolver.lookup(text).senses.find(x=>(x.source==='user'||personal(x.id))&&!x.zh.startsWith('释义待补充')),known=knownSelectionTranslation(text),prepared=preparedSelection(text);if(!own&&!known&&!prepared){void translateSelection();return;}modal('所选文字',`<blockquote lang="en">${esc(text)}</blockquote><div class="user-meaning">${own?markdownHTML(meaning(own)):known?esc(known):prepared?.exact?esc(prepared.text):'<p class="generation-help">选中片段所在句的参考译文</p>'+esc(prepared?.text||'')}</div><div class="button-row">${button('speak-selection','听所选文字','','btn primary',`data-text="${esc(text)}"`)}${button('stop-speech','停止朗读','','text-btn')}${prepared&&!prepared.exact&&!known&&!own?button('translate-selection','精确翻译所选片段','','btn subtle'):''}</div>`);}
async function translateSelection(){const text=selectedReadingText,known=knownSelectionTranslation(text);modal('选段释义',`<blockquote lang="en">${esc(text)}</blockquote><div class="selection-translation" role="status" aria-live="polite">${known?esc(known):'正在翻译，收到文字后立即显示…'}</div><div class="button-row">${button('speak-selection','听原文','','btn primary',`data-text="${esc(text)}"`)}${button('stop-speech','停止','','text-btn')}</div>`);const element=overlay.querySelector<HTMLElement>('.selection-translation')!;if(known)return;const controller=new AbortController(),observer=new MutationObserver(()=>{if(!element.isConnected){controller.abort();observer.disconnect();}});observer.observe(overlay,{childList:true});try{const translation=await translateLive(text,partial=>{if(element.isConnected){element.textContent=partial;element.dataset.state='streaming';}},controller.signal);if(!element.isConnected)return;element.textContent=translation;element.dataset.state='complete';}catch(e){if(element.isConnected){element.textContent=(e as Error).message;element.dataset.state='error';const connect=document.createElement('button');connect.className='btn subtle';connect.textContent='连接查询服务';connect.onclick=()=>void showServiceSettings(liveUI,()=>void translateSelection());element.after(connect);}}}

document.addEventListener('selectionchange',()=>{const selection=window.getSelection();if(!selection||selection.isCollapsed||!(selection.anchorNode instanceof Element?selection.anchorNode:selection.anchorNode?.parentElement)?.closest('.article-body')||!(selection.focusNode instanceof Element?selection.focusNode:selection.focusNode?.parentElement)?.closest('.article-body'))return;const range=selection.getRangeAt(0);selectedReadingText=[...document.querySelectorAll('[data-paragraph]')].filter(p=>range.intersectsNode(p)).map(p=>{const part=document.createRange();part.selectNodeContents(p);if(range.compareBoundaryPoints(Range.START_TO_START,part)>0)part.setStart(range.startContainer,range.startOffset);if(range.compareBoundaryPoints(Range.END_TO_END,part)<0)part.setEnd(range.endContainer,range.endOffset);return part.toString().trim();}).filter(Boolean).join('\n\n');if(!selectedReadingText){const old=document.getElementById('selection-tools');if(old)old.hidden=true;return;}let tools=document.getElementById('selection-tools');if(!tools){tools=document.createElement('div');tools.id='selection-tools';tools.className='selection-tools';tools.innerHTML=button('inspect-selection','查看选段意思','','btn primary')+button('speak-selection','听选段','','btn subtle')+button('stop-speech','停止','','text-btn');document.body.append(tools);}tools.hidden=false;});

document.addEventListener('cf-reading-ready',()=>{if(route()!=='read')return;document.querySelectorAll('.paragraph .translation>p').forEach((node,i)=>{const p=article()?.paragraphs[i];if(p&&!p.zh){const translated=cachedParagraph(p.en);if(translated)node.textContent=translated;}});});
